        }

        function markOpeningPlaying() {
          if (titleVisible || finished) {
            video.pause();
            videoBackdrop.pause();
            return;
          }
          needsGesture = false;
          soundGate.classList.toggle("is-visible",video.muted);
          soundGate.classList.toggle("is-sound-toggle",video.muted);
          if(video.muted)soundGate.innerHTML="开启声音<small>OP 正在静音自动播放</small>";
          playOpeningBackdrop();
        }

        function playOpeningWithSound() {
          if (titleVisible || finished) return;
          var attempt = ++playAttempt, revision = preludeRevision;
          function currentAttempt() {
            return attempt === playAttempt && revision === preludeRevision && !titleVisible && !finished;
          }
          function playing() { if(currentAttempt())markOpeningPlaying(); }
          video.defaultMuted = false;
          video.muted = false;
          video.volume = 1;
          var playPromise = video.play();
          if (!playPromise || typeof playPromise.then !== 'function') return;
          playPromise.then(playing).catch(function(error) {
            if(!currentAttempt() || error.name === 'AbortError')return;
            if(error.name !== 'NotAllowedError'){showSoundGate();return;}
            video.defaultMuted = true;
            video.muted = true;
            var silentPromise=video.play();
            if(silentPromise && typeof silentPromise.then === 'function')silentPromise.then(playing).catch(function(silentError){
              if(currentAttempt() && silentError.name !== 'AbortError')showSoundGate();
            });
          });
        }


        function revealTitle() {
          if (titleVisible || finished) return;
          titleVisible = true;
          playAttempt++;
          window.__openingOpActive = false;
          // 跳过后取消延迟启播，避免加载完成时重播隐藏的 OP。
          window.removeEventListener("load", playOpeningWithSound);
          video.pause();
          videoBackdrop.pause();
          openingScreen.classList.remove("is-active");
          openingScreen.setAttribute("aria-hidden", "true");
          titleScreen.classList.add("is-active");
          titleScreen.setAttribute("aria-hidden", "false");
          document.dispatchEvent(new CustomEvent("lk:title-visible"));
          continuePrompt.focus({ preventScroll: true });
        }

        function finishPrelude() {
          if (!titleVisible || finished) return;
          finished = true;
          playAttempt++;
          window.__openingOpActive = false;
          window.__lkPreludeComplete = true;
          document.body.classList.remove("prelude-active");
          setGuideInert(false);
          root.classList.add("is-finished");
          document.dispatchEvent(new CustomEvent("lk:prelude-complete"));
          window.scrollTo({top:0,behavior:"instant"});

          document.removeEventListener("keydown", handlePreludeKey, true);
          var finishRevision = preludeRevision;
          hidePreludeTimer = window.setTimeout(function () {
            if(finishRevision!==preludeRevision || !finished)return;
            root.hidden = true;
            if (messageHost) {
              messageHost.classList.remove("lk-prelude-host-active");
            }
          }, 450);
        }

        function handleOpeningClick(event) {
          if (event.target === soundGate || event.target === skipButton) return;
          if (needsGesture || video.paused) {
            playOpeningWithSound();
          } else {
            revealTitle();
          }
        }

        function handlePreludeKey(event) {
          if (finished || event.repeat) return;
          event.preventDefault();
          event.stopImmediatePropagation();
          if (!titleVisible) {
            if (needsGesture || video.paused) {
              playOpeningWithSound();
            } else {
              revealTitle();
            }
            return;
          }
          finishPrelude();
        }

        soundGate.addEventListener("click", function (event) {
          event.stopPropagation();
          playOpeningWithSound();
        });
        skipButton.addEventListener("click", function (event) {
          event.stopPropagation();
          revealTitle();
        });
        openingScreen.addEventListener("click", handleOpeningClick);
        titleScreen.addEventListener("click", finishPrelude);
        video.addEventListener("playing", markOpeningPlaying);
        video.addEventListener("timeupdate", function () {
          syncOpeningBackdrop(false);
        });
        video.addEventListener("seeking", function () {
          syncOpeningBackdrop(true);
        });
        video.addEventListener("ended", revealTitle);
        video.addEventListener("error", function(){
          if(titleVisible || finished)return;
          if(!opRemoteFallback && video.getAttribute("src")!==originalPreludeMedia.video){
            opRemoteFallback=true;window.__openingOpRemoteFallback=true;playAttempt++;
            [video,videoBackdrop].forEach(function(el){el.pause();el.src=originalPreludeMedia.video;el.load();});
            playOpeningWithSound();
          }else revealTitle();
        });
        videoBackdrop.addEventListener(
          "error",
          function () {
            videoBackdrop.hidden = true;
          },
          { once: true },
        );
        document.addEventListener("keydown", handlePreludeKey, true);
        window.OpeningPrelude = {replay: function() {
          preludeRevision++; playAttempt++; clearTimeout(hidePreludeTimer);
          video.pause(); videoBackdrop.pause();
          var bgm=document.getElementById("bgm-audio");if(bgm)bgm.pause();
          finished=false;titleVisible=false;needsGesture=false;
          window.__lkPreludeComplete=false;window.__openingOpActive=true;
          document.dispatchEvent(new CustomEvent("lk:prelude-start"));
          root.hidden=false;root.classList.remove("is-finished");videoBackdrop.hidden=false;
          openingScreen.classList.add("is-active");openingScreen.setAttribute("aria-hidden","false");
          titleScreen.classList.remove("is-active");titleScreen.setAttribute("aria-hidden","true");
          if(messageHost)messageHost.classList.add("lk-prelude-host-active");else document.body.classList.add("prelude-active");
          document.addEventListener("keydown",handlePreludeKey,true);setGuideInert(true);
          try{video.currentTime=0;videoBackdrop.currentTime=0;}catch(error){}
          playOpeningWithSound();
        }};
        if(new URLSearchParams(location.search).get("skipIntro")==="1") {
          titleVisible=true;finishPrelude();return;
        }
        window.addEventListener("pagehide",function(){preludeRevision++;clearTimeout(hidePreludeTimer);video.pause();videoBackdrop.pause();});
        function activatePreludeScope() {
          setGuideInert(true);
        }

        if (document.readyState === "loading") {
          document.addEventListener("DOMContentLoaded", activatePreludeScope, {
            once: true,
          });
        } else {
          activatePreludeScope();
        }

        playOpeningWithSound();
      })();
    </script>

