          return el;
        }

        // 1. 外框大六边形轮廓线
        var outerPts = axes
          .map(function (_, i) {
            return polar(R_outer, i).join(",");
          })
          .join(" ");
        svg.appendChild(
          svgEl("polygon", {
            points: outerPts,
            fill: "none",
            stroke: "#262220",
            "stroke-width": 2.5,
          }),
        );

        // 2. 内部同心正六边形网格
        [0.25, 0.5, 0.75].forEach(function (ratio) {
          var gridPts = axes
            .map(function (_, i) {
              return polar(R_outer * ratio, i).join(",");
            })
            .join(" ");
          svg.appendChild(
            svgEl("polygon", {
              points: gridPts,
              fill: "none",
              stroke: "#3d352e",
              "stroke-width": 1.2,
              opacity: 0.65,
            }),
          );
        });

        // 3. 中心放射径向轴线
        axes.forEach(function (_, i) {
          var end = polar(R_outer, i);
          svg.appendChild(
            svgEl("line", {
              x1: cx,
              y1: cy,
              x2: end[0],
              y2: end[1],
              stroke: "#3d352e",
              "stroke-width": 1.2,
              opacity: 0.7,
            }),
          );
        });

        // 4. 橙红色半透明数据填充多边形
        var hasData = axes.some(function (ax) {
