        if (original && Object.hasOwn(original, '名册隐藏')) {
          restore(relation, '名册隐藏', original.名册隐藏, '/人际/' + name + '/名册隐藏');
        } else if (Object.hasOwn(relation, '名册隐藏')) {
          delete relation.名册隐藏;
          changed.push('/人际/' + name + '/名册隐藏');
        }
