  // 通知挂在酒馆宿主上，终端是否展开不影响状态；关闭通知也不会取消后台任务。
  function installHostCorrectionNotice() {
    const notice = HD.createElement('section');
    notice.id = 'rk-correction-notice'; notice.hidden = true;
