    if (!record) throw new Error('操作凭据已失效，请重新读取当前分支。');
    if (record.kind !== kind) throw new Error('操作凭据用途不符；迁移必须通过明确的升级操作提交。');
    if (operationScope !== 'full' && record.scope !== 'full' && record.scope !== operationScope) throw new Error('操作范围已变化，请重新读取后再执行。');
    const scope = operationScope === 'full' ? 'full' : record.scope;
    if (record.busy) throw new Error('正在写入，请勿重复操作。');
    record.busy = true;
    try {
      const checkWritable = () => {
        if (assertWritable && assertWritable()?.then) throw new Error('写入前检查必须同步完成。');
      };
      checkWritable();
      if (openingReplacement) assertReplacementScope(record.snapshot);
      const candidate = adapter.validate(build(cloneState(record.state)), scope);
      if (record.done) {
        if (stateKey(candidate) !== stateKey(record.done)) throw new Error('同一凭据只能重试原操作，请重新读取后再执行新操作。');
        const now = await adapter.current(record.snapshot);
        if (openingReplacement) assertReplacementScope(record.snapshot);
        if (stateKey(adapter.validate(now.data.stat_data, scope)) !== stateKey(record.done)) throw new Error('当前状态已变化，请刷新。');
        return { state: cloneState(record.done), alreadyApplied: true };
      }
      const current = await adapter.current(record.snapshot);
      if (openingReplacement) assertReplacementScope(record.snapshot);
      // API 返回异常但写入已落地时，仅确认匹配结果，绝不再写一遍。
      if (current.data.stat_data?.系统?.结构版本 === 4 && stateKey(adapter.validate(current.data.stat_data, scope)) === stateKey(candidate)) {
        record.done = candidate;
        record.doneScope = scope;
        record.openingReplacement = openingReplacement;
        return { state: cloneState(candidate), alreadyApplied: true };
      }
      if (stateKey(current.data) !== stateKey(record.snapshot.data)) throw new Error('变量已被其他操作更新，请重新读取，草稿已保留。');
      if (openingReplacement) assertReplacementScope(record.snapshot);
      checkWritable();
      await adapter.write(record.snapshot, current.data, candidate, { openingReplacement });
      const persisted = await adapter.current(record.snapshot);
      if (openingReplacement) assertReplacementScope(record.snapshot);
      const result = adapter.validate(persisted.data.stat_data, scope);
      if (stateKey(result) !== stateKey(candidate)) throw new Error('回读与提交内容不一致，未确认写入成功；请检查 MVU 通知后刷新。');
      record.done = result;
      record.doneScope = scope;
      record.openingReplacement = openingReplacement;
      return { state: cloneState(result) };
    } finally { record.busy = false; }
  }
  return Object.freeze({
    version: '4.0.0', get catalogue() { return cloneState(STORY_VOLUMES); }, capture, prepareMigration,
    capabilities: Object.freeze({ scheduleAndRoster: true, rosterPermanentRemoval: true, ocPlayerEditing: true,
      tournament: 'T01', tournamentEngine: 'T02', nativeMvu: 'N01' }),
    get growthRules() { return cloneState(GROWTH_RULES); },
    tournamentView: state => deriveTournament(requireRakudaiState(state)),
    nationalTournamentView: state => deriveNationalTournament(requireRakudaiState(state)),
    isHagunAffiliation,
    shouldInjectTournament: state => resolveMvuWorld(state) === 'rakudai' && shouldInjectTournament(state),
    shouldInjectNationalTournament: state => resolveMvuWorld(state) === 'rakudai' && shouldInjectNationalTournament(state),
    setDorm: (token, active) => commit(token, state => {
      if (resolveMvuWorld(state) !== 'rakudai') throw new Error('当前作品未启用落第宿舍操作。');
      if (typeof active !== 'boolean' || state.系统.开局状态 !== '已建档') throw new Error('请先完成建档，再进入宿舍。');
      return { ...state, 场景: { ...state.场景, 宿舍: active } };
    }, 'state', false, 'dorm'),
    tournamentAction: (token, request) => commit(token, state => { if (resolveMvuWorld(state) !== 'rakudai') throw new Error('当前作品未启用落第赛事操作。'); return prepareTournamentAction(state, request); }, 'state', false, request?.action === 'upsertQualification' ? 'qualification' : ['upsertNationalMatch', 'upsertNationalAdvancement', 'setNationalSchedule'].includes(request?.action) ? 'national' : 'tournament'),
    tournamentOpponents: (state, options) => suggestTournamentOpponents(requireRakudaiState(state), options),
    tournamentParticipant: (state, options) => createTournamentParticipant(requireRakudaiState(state), options),
    commitMigration: token => commit(token, state => state, 'migration'),
    verify: async token => {
      const record = tokens.get(token);
      if (!record?.done) throw new Error('尚无已回读确认的建档结果。');
      const now = await adapter.current(record.snapshot);
      if (record.openingReplacement) assertReplacementScope(record.snapshot);
      const state = adapter.validate(now.data.stat_data, record.doneScope);
      if (stateKey(state) !== stateKey(record.done)) throw new Error('本局状态已变化，请刷新后继续。');
      return { state: cloneState(state) };
    },
    commitOpening: (token, payload) => commit(token, state => applyOpening(state, payload)),
    replaceOpening: (token, payload) => commit(token, state => applyOpeningReplacement(state, payload), 'state', true),
    transition: (token, request) => commit(token, state => applyTransition(state, request), 'state', false, 'story'),
    editPlayerProfile: (token, request, assertWritable) => commit(token, state => editOcPlayerProfile(state, request), 'state', false, 'player-profile', assertWritable),
    setRosterHidden: (token, name, hidden) => commit(token, state => {
      if (typeof name !== 'string' || !name.trim() || /[~/]/.test(name) ||
          ['__proto__', 'prototype', 'constructor'].includes(name) || typeof hidden !== 'boolean') throw new Error('名册操作参数不合法。');
      if (state.系统.开局状态 !== '已建档' || !Object.hasOwn(state.人际, name)) throw new Error('当前分支没有该人物档案，请刷新名册。');
      if (!state.人际[name] || typeof state.人际[name] !== 'object' || Array.isArray(state.人际[name])) throw new Error('该人物资料不是对象，无法修改显示状态。');
      state.人际[name].名册隐藏 = hidden;
      return state;
    }, 'state', false, 'roster'),
    deleteRosterPerson: (token, name) => commit(token, state => {
      if (typeof name !== 'string' || !name.trim() || /[~/]/.test(name) ||
          ['__proto__', 'prototype', 'constructor'].includes(name)) throw new Error('人物名称不合法。');
      if (state.系统.开局状态 !== '已建档' || !Object.hasOwn(state.人际, name)) throw new Error('当前回复页没有该人物资料，请刷新名册。');
      delete state.人际[name];
      state.系统.已删除人物 = [...new Set([...(state.系统.已删除人物 || []), name])];
      return state;
    }, 'state', false, 'roster'),
  });
}

// 主约束与可选成长脚本共用真实回复来源；不读聊天级变量、不保存聊天。
function replyMvuBlock(content) {
  if (typeof content !== 'string') return '';
  const text = content.replace(/\r\n?/g, '\n');
  if ((text.match(/<UpdateVariable>/gi) || []).length !== 1 ||
      (text.match(/<\/UpdateVariable>/gi) || []).length !== 1) return '';
  const block = text.match(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/i)?.[0];
  if (!block || (block.match(/<json_?patch>/gi) || []).length !== 1 ||
      (block.match(/<\/json_?patch>/gi) || []).length !== 1) return '';
  const patch = block.match(/<(json_?patch)>([\s\S]*?)<\/\1>/i);
  try { return patch && Array.isArray(JSON.parse(patch[2].trim())) ? block : ''; }
  catch (_) { return ''; }
}

// 副修复由调用方明确绑定真实回复；无有效主补丁时保留正文作为来源。
// MVU 自动追加的末尾显示占位符不是剧情编辑，不应让同一回复的修复过期。
function repairReplyText(content) {
  if (typeof content !== 'string') return '';
  return replyMvuBlock(content) || content.replace(/\r\n?/g, '\n')
    .replace(/(?:\s*<StatusPlaceHolderImpl\s*\/>)+\s*$/i, '').trim();
}

function replyPatchOperations(content) {
  const block = replyMvuBlock(content), patch = block.match(/<(json_?patch)>([\s\S]*?)<\/\1>/i);
  try { return patch ? JSON.parse(patch[2].trim()) : []; }
  catch (_) { return []; }
}

function replyPatchParts(op) {
  if (!op || !['add', 'replace'].includes(op.op) || typeof op.path !== 'string' ||
      !op.path.startsWith('/') || /~(?![01])/.test(op.path)) return null;
  const parts = op.path.slice(1).split('/').map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
  return parts.some(part => !part || ['__proto__', 'prototype', 'constructor'].includes(part)) ? null : parts;
}

// 明确提交的最终数值支持叶字段与父对象写法；奖励重放不能再次加分。
function submittedFinals(content) {
  const fields = [], growthFinalAxes = new Set(), growthGradeAxes = new Set();
  function inspect(parts, value) {
    if (parts[0] === '人际' && parts.length === 3 && ['好感', '支援度'].includes(parts[2]) &&
        (typeof value === 'number' && Number.isFinite(value) || value === null)) fields.push([JSON.stringify([parts[1], parts[2]]), value]);
    if (parts.length === 4 && parts[0] === '玩家' && parts[1] === '成长' && parts[2] === '经验' && GROWTH_AXES.includes(parts[3])) growthFinalAxes.add(parts[3]);
    if (parts.length === 3 && parts[0] === '玩家' && parts[1] === '六维' && GROWTH_AXES.includes(parts[2])) growthGradeAxes.add(parts[2]);
    if (!value || typeof value !== 'object' || Array.isArray(value)) return;
    for (const [key, child] of Object.entries(value)) if (!['__proto__', 'prototype', 'constructor'].includes(key)) inspect([...parts, key], child);
  }
  for (const op of replyPatchOperations(content)) {
    const parts = replyPatchParts(op);
    if (parts) inspect(parts, op.value);
  }
  return { fields, growthFinalAxes: [...growthFinalAxes], growthGradeAxes: [...growthGradeAxes] };
}

// 副补丁只能补领真实正文已提交且已经保存的本轮事件，不凭副模型自称认来源。
function savedReplyEventKeys(content, state) {
  const keys = [], events = state?.场景?.已发生事件;
  const object = value => value && typeof value === 'object' && !Array.isArray(value);
  function remember(name, result) {
    if (typeof name !== 'string' || !name || /[~/]/.test(name) || ['__proto__', 'prototype', 'constructor'].includes(name) ||
        typeof result !== 'string' || !result.trim() || !object(events) || !Object.hasOwn(events, name) ||
        result !== events[name]?.结果 || keys.includes(name)) return;
    keys.push(name);
  }
  function rememberObject(value) {
    if (object(value)) for (const [name, event] of Object.entries(value)) {
      if (object(event) && Object.hasOwn(event, '结果')) remember(name, event.结果);
    }
  }
  for (const op of replyPatchOperations(content)) {
    const parts = replyPatchParts(op);
    if (!parts || parts[0] !== '场景') continue;
    if (parts.length === 1 && object(op.value) && Object.hasOwn(op.value, '已发生事件')) rememberObject(op.value.已发生事件);
    else if (parts[1] === '已发生事件') {
      if (parts.length === 2) rememberObject(op.value);
      else if (parts.length === 3) remember(parts[2], object(op.value) ? op.value.结果 : null);
      else if (parts.length === 4 && parts[3] === '结果') remember(parts[2], op.value);
    }
  }
  return keys;
}

function createRakudaiMvuReplySource(W, { mvu = W.Mvu, enrichRepairSource = source => source,
  assertRepairAvailable = () => {} } = {}) {
  const H = (function() {
    for (const resolve of [() => W.top, () => W.parent, () => W]) {
      try { const scope = resolve(); if (scope?.SillyTavern?.getContext) return scope; } catch (_) {}
    }
    return W;
  })();
  const parsingSources = new WeakMap();
  let repairSession = null;
  function replyContext() {
    const ctx = H.SillyTavern?.getContext();
    return ctx?.chatId !== undefined && ctx.chatId !== null && ctx.chatId !== '' &&
      Array.isArray(ctx.chat) && ctx.chat.length ? ctx : null;
  }
  function replyOwner() {
    const owner = typeof W.getChatMessages === 'function' ? W : W.TavernHelper;
    return typeof owner?.getChatMessages === 'function' ? owner : null;
  }
  function readReply(ctx, owner, messageId, repairBound = false) {
    if (!Number.isInteger(messageId) || messageId < 0 || messageId >= ctx.chat.length) return null;
    // mes 是宿主正在保存的正文，swipes 可能稍后更新；它仅提供当前页号。
    const active = owner.getChatMessages(String(messageId), { role: 'assistant' })?.[0];
    const page = owner.getChatMessages(String(messageId), { role: 'assistant', include_swipes: true })?.[0];
    if (active?.message_id !== messageId || page?.message_id !== messageId || !Number.isInteger(page.swipe_id)) return null;
    const block = repairBound ? repairReplyText(active.message) : replyMvuBlock(active.message), messageRef = ctx.chat[messageId];
    if (!block || !messageRef) return null;
    return { chatId: ctx.chatId, characterId: ctx.characterId, groupId: ctx.groupId,
      messageId, swipeId: page.swipe_id, chatRef: ctx.chat, messageRef, text: block,
      ...(repairBound ? { repairBound: true } : {}),
      key: JSON.stringify([ctx.characterId ?? null, ctx.groupId ?? null, ctx.chatId, messageId, page.swipe_id]) };
  }
  function locateBoundReply(content, identity) {
    const block = replyMvuBlock(content), ctx = replyContext(), owner = replyOwner();
    if (!block || !ctx || !owner || !identity || identity.chatRef !== ctx.chat ||
        identity.chatId !== ctx.chatId || (identity.characterId ?? null) !== (ctx.characterId ?? null) ||
        (identity.groupId ?? null) !== (ctx.groupId ?? null)) return null;
    const source = readReply(ctx, owner, identity.messageId);
    return source && source.messageRef === identity.messageRef && source.swipeId === identity.swipeId &&
      source.text === block ? source : null;
  }
  function locateRepairReply(content, identity) {
    const text = repairReplyText(content), ctx = replyContext(), owner = replyOwner();
    if (!text || !ctx || !owner || !identity || typeof identity !== 'object' || Array.isArray(identity) ||
        !Number.isSafeInteger(identity.messageId) || identity.messageId < 0 ||
        !Number.isSafeInteger(identity.swipeId) || identity.swipeId < 0 ||
        identity.chatRef !== ctx.chat || identity.chatId !== ctx.chatId ||
        (identity.characterId ?? null) !== (ctx.characterId ?? null) ||
        (identity.groupId ?? null) !== (ctx.groupId ?? null)) return null;
    const source = readReply(ctx, owner, identity.messageId, true);
    return source && source.messageRef === identity.messageRef && source.swipeId === identity.swipeId &&
      source.text === text ? source : null;
  }
  function locateReply(content) {
    const block = replyMvuBlock(content), ctx = replyContext(), owner = replyOwner();
    if (!block || !ctx || !owner) return null;
    const messages = owner.getChatMessages(`0-${ctx.chat.length - 1}`, { role: 'assistant' });
    if (!Array.isArray(messages)) return null;
    const matches = messages.filter(message => Number.isInteger(message.message_id) && replyMvuBlock(message.message) === block);
    if (matches.length !== 1) return null;
    const source = readReply(ctx, owner, matches[0].message_id);
    return source?.text === block ? source : null;
  }
  function capture(variables, content) {
    if (!variables || typeof variables !== 'object') return;
    parsingSources.delete(variables);
    try {
      let source = locateReply(content);
      if (repairSession && !repairSession.claimed && content === repairSession.content) {
        source = repairSession.source;
        repairSession.claimed = true;
      }
      if (source) {
        const finals = submittedFinals(content);
        parsingSources.set(variables, { ...source, submittedFields: finals.fields,
          growthFinalAxes: finals.growthFinalAxes, growthGradeAxes: finals.growthGradeAxes });
      }
    } catch (_) { /* 无真实身份则不给本轮额度，保留其他事实更新。 */ }
  }
  function take(variables) {
    const source = parsingSources.get(variables);
    parsingSources.delete(variables);
    let replyKey = '';
    if (source) {
      try {
        const now = source.repairBound ? locateRepairReply(source.text, source) : locateBoundReply(source.text, source);
        if (now && now.key === source.key) replyKey = source.key;
      } catch (_) {}
    }
    return { source, replyKey };
  }
  async function parseRepair(content, data, sourceText, identity) {
    assertRepairAvailable();
    if (repairSession) throw new Error('已有副 API 补丁正在解析。');
    try { if (!Array.isArray(JSON.parse(content))) throw new Error(); }
    catch (_) { throw new Error('副 API 补丁必须是完整的 JSON 数组，未解析。'); }
    const source = locateRepairReply(sourceText, identity);
    if (!source) throw new Error('无法唯一确认补丁对应的助手回复，未解析。');
    const nonce = Math.random().toString(36).slice(2);
    const wrapped = '<UpdateVariable><Analysis>repair:' + nonce + '</Analysis><JSONPatch>' +
      content + '</JSONPatch></UpdateVariable>';
    repairSession = { content: wrapped, source: enrichRepairSource({ ...source,
      repairEventKeys: savedReplyEventKeys(source.text, data.stat_data), flexibleRepair: true }, identity), claimed: false };
    try {
      const result = await mvu.parseMessage(wrapped, structuredClone(data));
      assertRepairAvailable();
      if (!locateRepairReply(source.text, source)) throw new Error('聊天、回复页或 MVU 来源已变化，未采用补丁。');
      return result;
    } finally { repairSession = null; }
  }
  return { host: H, capture, take, locateReply, locateBoundReply, locateRepairReply, parseRepair };
}

// 内联依赖 rakudai-mvu-reply-source.mjs；在 Zod 桥接注册后调用。
function installRakudaiMvuGuard(schema) {
  if (typeof eventOn !== 'function' || !Mvu.events?.VARIABLE_UPDATE_ENDED) throw new Error('MVU 缺少更新结束事件，写入责任保护未注册。');
  const H = (function() {
    for (const resolve of [() => window.top, () => window.parent, () => window]) {
      try { const scope = resolve(); if (scope?.SillyTavern?.getContext) return scope; } catch (_) {}
    }
    return window;
  })();
  // 仅缓存真实回复的主结算起止点；正文/生图刷新不会重置同轮推进记录。
  const storySettlements = new Map();
  function storyPoint(scene) {
    if (!scene || storyPosition(scene.当前卷, scene.当前章) < 0 || !['未开始', '进行中', '已结束'].includes(scene.阶段)) return null;
    return { 当前卷: scene.当前卷, 当前章: resolveStoryChapter(scene.当前卷, scene.当前章).key, 阶段: scene.阶段 };
  }
  function storyReceipt(source) {
    const saved = storySettlements.get(source.key);
    return saved && saved.chatRef === source.chatRef && saved.messageRef === source.messageRef && saved.text === source.text ? saved : null;
  }
  function rememberStory(source, before, after) {
    const start = storyPoint(before), end = storyPoint(after);
    if (!source || !start || !end) return;
    const saved = storyReceipt(source);
    storySettlements.delete(source.key);
    storySettlements.set(source.key, { chatRef: source.chatRef, messageRef: source.messageRef, text: source.text,
      before: saved?.before || start, after: end });
    if (storySettlements.size > 300) storySettlements.delete(storySettlements.keys().next().value);
  }
  const replySources = createRakudaiMvuReplySource(window, { mvu: Mvu,
    enrichRepairSource: (source, identity) => ({ ...source, relationshipCorrection: true,
      storyCorrection: true, storyBefore: storyReceipt(source)?.before || storyPoint(identity.storyBefore) }),
  });
  const parseRepair = replySources.parseRepair;
  const commandListener = Mvu.events.COMMAND_PARSED ? eventOn(Mvu.events.COMMAND_PARSED,
    (variables, commands, content) => replySources.capture(variables, content)) : null;
  const listener = eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, previous) => {
    let changed;
    let scoreNotices = [];
    let contactChanges = [];
    let growthNotices = [];
    let tournamentNotices = [];
    const internal = variables?.stat_data?.$internal;
    function rollback() {
      variables.stat_data = cloneState(previous.stat_data);
      if (internal !== undefined) variables.stat_data.$internal = internal;
    }
    try {
      const { source, replyKey } = replySources.take(variables);
      const flexibleRepair = Boolean(replyKey && source?.flexibleRepair === true);
      changed = enforceStateOwnership(variables, previous, { replyKey, flexibleRepair,
        storyCorrection: source?.storyCorrection === true, storyBefore: source?.storyBefore });
      scoreNotices = enforceRelationshipScores(variables, previous, { replyKey, submittedFields: source?.submittedFields || [],
        relationshipCorrection: Boolean(replyKey && source?.relationshipCorrection === true), flexibleRepair });
      contactChanges = enforceRelationshipContact(variables, previous, { replyKey, flexibleRepair });
      // 选拔赛只校验自身账本；坏比赛不回滚能力、人际或其它本轮事实。
      if (resolveMvuWorld(previous?.stat_data) === 'rakudai') tournamentNotices = enforceTournamentState(variables, previous);
      const scoreReceiptChanged = stateKey(variables.stat_data?.系统?.关系计分) !== stateKey(previous.stat_data?.系统?.关系计分);
      growthNotices = enforceGrowthProgress(variables, previous, { mode: 'final', replyKey,
        repairEventKeys: replyKey ? source?.repairEventKeys || [] : [],
        growthFinalAxes: source?.growthFinalAxes || [], growthGradeAxes: source?.growthGradeAxes || [] });
      const storyChanged = ['当前卷', '当前章', '阶段'].some(key => variables.stat_data?.场景?.[key] !== previous.stat_data?.场景?.[key]);
      const growthChanged = stateKey(variables.stat_data?.玩家?.成长) !== stateKey(previous.stat_data?.玩家?.成长);
      // 合法相邻推进和越权恢复后都校验事件位置，不能留下超前事件。
      // 关系计分被拒时仍不牵连其他字段。
      if ((changed.length || contactChanges.length || storyChanged || growthChanged || scoreReceiptChanged) && !schema.safeParse(variables.stat_data).success) {
        rollback();
        changed.push('/场景（更新后结构或事件位置不合法）');
      }
      // 主回复无变化也要保存起点；副补漏首次推进后沿用同一起点，防止再次校正跳两章。
      if (replyKey && resolveMvuWorld(previous?.stat_data) === 'rakudai') rememberStory(source, source.storyCorrection ? source.storyBefore : previous.stat_data?.场景, variables.stat_data?.场景);
    } catch (_) { rollback(); changed = ['/stat_data']; }
    if (changed.length) {
      const message = '已恢复越权或非法修改：' + changed.join('、') + '。自动切章只允许按当前世界书完成标识或既定路线交接；其他切入请使用终端。';
      console.warn('[落第 MVU v4] ' + message);
      if (typeof toastr !== 'undefined') toastr.warning(message, '写入责任检查');
    }
    if (scoreNotices.length) {
      const message = scoreNotices.map(item => item.path + '：' + item.message).join('\n');
      console.warn('[落第 MVU v4 关系计分] ' + message);
      if (typeof toastr !== 'undefined') toastr.warning(message, '关系计分检查');
    }
    if (tournamentNotices.length) {
      const message = tournamentNotices.join('\n');
      console.warn('[落第 MVU 选拔赛] ' + message);
      if (typeof toastr !== 'undefined') toastr.warning(message, '选拔赛记录检查');
    }
