ss=\"ax-note\">以上台词为界面排版示例，不是原作引文，也不表示本局已发生对话。\u003c/p>';\n  }\n\n  function closeToWheel() {\n    if (dialog.open) dialog.close();\n    try {\n      if (bridge && bridge.ui && typeof bridge.ui.openWheel === 'function') { bridge.ui.openWheel(); return; }\n      if (bridge && bridge.ui && typeof bridge.ui.close === 'function') { bridge.ui.close(); return; }\n      notify('当前没有连接轮盘宿主。');\n    } catch (error) { notify(valueText(error && error.message, '终端暂时无法收起。')); }\n  }\n\n  document.addEventListener('change', function (event) {\n    if (event.target.matches('select[data-terminal-appearance]') && bridge && bridge.appearance) bridge.appearance.set(event.target.value);\n  });\n  document.addEventListener('input', function (event) {\n    var field = event.target.dataset.correctionField;\n    if (!field || !correctionEditor) return;\n    correctionEditor[field] = field === 'autoApply' ? event.target.checked : event.target.value;\n    correctionAction++; correctionPreview = null; bridge.correction.cancel();\n    var apply = content.querySelector('[data-correction-action=\"apply\"]'); if (apply) apply.disabled = true;\n    var preview = document.getElementById('ax-correction-preview'); if (preview) preview.hidden = true;\n  });\n  document.addEventListener('click', function (event) {\n    var button = event.target.closest('button'); if (!button) return;\n    if (button.dataset.plotAction) { runPlotAction(button.dataset.plotAction); return; }\n    if (button.dataset.correctionAction) { runCorrectionAction(button.dataset.correctionAction); return; }\n    if (button.dataset.app) { openApp(button.dataset.app); return; }\n    if (button.dataset.action === 'home') { openApp('home'); return; }\n    if (button.dataset.action === 'close') { closeToWheel(); return; }\n    if (button.dataset.action === 'dismiss') { dialog.close(); return; }\n    if (button.dataset.action === 'refresh') { refreshTerminalState().then(function () { notify(dataStatus === 'ready' ? '已重新读取宿主快照。' : '已完成读取检查，请查看数据状态。'); }); return; }\n    if (button.dataset.action === 'motion') {\n      var mode = document.documentElement.getAttribute('data-ax-motion') === 'reduced';\n      document.documentElement.setAttribute('data-ax-motion', mode ? 'system' : 'reduced'); render();\n      content.querySelector('[data-action=\"motion\"]')?.focus(); return;\n    }\n    if (button.dataset.person !== undefined) {\n      var index = Number(button.dataset.person); if (!people[index]) return;\n      lastDialogOpener = button; activePortrait = index; dialogueMode = 'short'; renderPortraitDialog(); dialog.showModal(); return;\n    }\n    if (button.dataset.dialogue) { dialogueMode = button.dataset.dialogue === 'long' ? 'long' : 'short'; renderPortraitDialog(); dialogBody.querySelector('[data-dialogue=\"' + dialogueMode + '\"]')?.focus(); }\n  });\n  dialog.addEventListener('click', function (event) {\n    if (event.target !== dialog) return;\n    var rect = dialog.getBoundingClientRect();\n    if (event.clientX \u003c rect.left || event.clientX > rect.right || event.clientY \u003c rect.top || event.clientY > rect.bottom) dialog.close();\n  });\n  dialog.addEventListener('close', function () { if (lastDialogOpener && lastDialogOpener.isConnected) lastDialogOpener.focus({ preventScroll: true }); });\n  document.addEventListener('error', function (event) {\n    var img = event.target;\n    if (!img || img.tagName !== 'IMG') return;\n    if (img.classList.contains('ax-holo-emblem')) { img.hidden = true; return; }\n    var holder = img.parentElement;\n    if (holder && (holder.classList.contains('ax-portrait') || holder.classList.contains('ax-dialogue-avatar'))) { holder.classList.add('ax-missing-media'); holder.setAttribute('aria-label', '原图暂不可用'); }\n  }, true);\n\n  window.RKBoot = function (nextBridge) {\n    if (typeof unsubscribe === 'function') unsubscribe();\n    unsubscribe = null; bridgeRevision++; requestRevision++;\n    bridge = nextBridge || null;\n    correctionAction++; correctionEditor = null; correctionPreview = null; correctionMessage = '';\n    plotRequest++; plotStatus = null; plotPreview = null; plotError = ''; plotBusy = false;\n    state = {}; snapshot = null; snapshotSignature = ''; dataStatus = 'loading'; dataMessage = '';\n    render();\n    if (bridge && typeof bridge.onUpdate === 'function') unsubscribe = bridge.onUpdate(function (event) {\n      if (event?.reset && !['show', 'correction-applied'].includes(event.type)) {\n        correctionAction++; correctionPreview = null; correctionMessage = '';\n        if (['CHAT_CHANGED', 'CHARACTER_FIRST_MESSAGE_SELECTED'].includes(event.type)) correctionEditor = null;\n      }\n      if (event?.type === 'correction-preview') { correctionPreview = event.result; correctionMessage = event.result.count + ' 项待检查，尚未写入。'; if (currentApp === 'settings') render(); }\n      else if (event?.type === 'correction-status') {\n        var status = bridge.correction?.getStatus();\n        if (status && status.state !== 'preview') { correctionPreview = null; var apply = content.querySelector('[data-correction-action=\"apply\"]'); if (apply) apply.disabled = true; }\n        var node = document.getElementById('ax-correction-status'); if (node && status) node.textContent = status.message;\n      }\n      refreshTerminalState();\n    });\n    return refreshTerminalState();\n  };\n  window.openApp = openApp;\n  window.goHome = function () { return openApp('home'); };\n  window.refreshTerminalState = refreshTerminalState;\n  window.addEventListener('pagehide', function () { bridgeRevision++; requestRevision++; correctionAction++; clearTimeout(toastTimer); if (typeof unsubscribe === 'function') unsubscribe(); unsubscribe = null; });\n  render();\n})();\n\u003c/script>\n\u003c/body>\n\u003c/html>\n";
  const RIKKA_ICON_SRC = "data:image/png;base64,";
  const RELATIONSHIP_SCORING = {"version":"R10-按回复分项结算","affection":{"min":0,"max":1000,"initial":0,"ordinaryMin":2,"ordinaryMax":10,"mediumMin":11,"mediumMax":20,"majorMin":21,"majorMax":40,"decrease":{"ordinaryMin":1,"ordinaryMax":5,"mediumMin":6,"mediumMax":10,"majorMin":11,"majorMax":20},"backgroundMin":70,"backgroundMax":200},"support":{"min":0,"max":320,"initial":0,"ordinaryMin":1,"ordinaryMax":5,"mediumMin":6,"mediumMax":10,"majorMin":10,"majorMax":15,"stages":[{"stage":"C","min":80},{"stage":"B","min":160},{"stage":"A","min":240},{"stage":"S","min":320}]},"romance":{"stages":[{"stage":"路人","min":0},{"stage":"在意","min":200},{"stage":"暧昧","min":500},{"stage":"交往","min":800},{"stage":"生死相随","min":1000}]}};
  const CORRECTION_RULES = "【变量更新规则】\n\u003c% const updateSystem = getvar('stat_data.系统') || {}; const updatePlayer = getvar('stat_data.玩家') || {}; const rkObject = value => value !== null && typeof value === 'object' && !Array.isArray(value); const updateWorld = Object.prototype.hasOwnProperty.call(updateSystem, '作品') ? updateSystem.作品 : (updateSystem.结构版本 === 4 && updateSystem.开局状态 === '已建档' ? 'rakudai' : null); const hasBladeGrowth = rkObject(updatePlayer.伐刀能力) && rkObject(updatePlayer.六维); if (updateSystem.开局状态 !== '已建档' || !['rakudai','asterisk'].includes(updateWorld)) { %>\n本局尚未确认有效作品与人物档案。由开局页完成建档，本轮 JSONPatch 为 []，不要自行初始化、推章或套用任一作品的能力规则。\n\u003c% } else { %>\n本局主线为 \u003c%= updateWorld === 'asterisk' ? '学战都市' : '落第骑士' %>。\n核对旧值与本轮事实，只提交变化后的最终值。本局事实优先于原著走向和模型记忆；计划与预告不算已完成。\n主副 API 权限相同。主回复当轮核对场景、能力、成长、人际与赛事，不等副 API 或玩家提醒。补漏与重试不重复结算同一成果。\n\n【保存与字段】\n已建档不重建；v2/v3 先经终端迁移；一辉模式不另建同名 NPC。\n字段权限见输出格式；旧成长申请与收据只读留档。\n玩家资料、能力、六维、登记等级、成长经验、人际资料与分数均可按已确认事实修正；确认错误的条目可以删除，离场或暂时失效不等于删除。\n首次取得能力或装备时记录实际所得，之后只更新变化项。\n\n【能力与装备】\n人物拥有什么就记什么，不因本局选的是哪部作品而禁止。\n- 伐刀能力：能力系别、能力本质、共通限制、招式。剑术、体术、分析、生活技艺归 /玩家/其他能力。\n- 固有灵装：文本字段，按事实记录。\n- 学战来源的能力与装备：按需在 /玩家/学战 下新增。武装记类别、名称、使用条件；校内序列只表示所属学园排名；星辰力只用说明记录，不编造数值。\n两套招式分别保存，不互相覆盖或合并。\n获得伐刀能力不等于魔人觉醒。只有本局明确成为魔人，才把 /玩家/魔人觉醒 写为 true；误记可按事实纠正，觉醒本身不赠经验。\n有煌武不等于有星辰力或学籍；有伐刀能力不等于入学，也不改 /系统/作品 或主线归属。\n六维保存实际档位；永久成长与评级纠错可改六维，临时强化、疲劳或受伤写在描述中。正式登记或重评才改登记等级，开局综合初评保留历史。\n不设统一 HP/MP/AP/SP，不把原作比例换算成自造消耗数值。\n\n【成长终值】\n结算须有完整的 /玩家/伐刀能力 与 /玩家/六维，评级未知时不猜起点。\n\u003c% if (!hasBladeGrowth) { %>\n当前档案尚缺完整能力或六维。本轮确认获得伐刀能力并完成六维评定时，可先新增缺少的对象，再结算同轮此后真实发生的训练；否则不新增成长经验。\n\u003c% } %>\n\u003c% if (updatePlayer.魔人觉醒 === true) { %>\n魔人觉醒:true。魔力控制、体能、魔力量可按本轮实际成果成长，已有觉醒不再复核。\n\u003c% } else { %>\n魔人觉醒:false。魔力控制、体能可成长，魔力量不获新成长经验；本轮明确觉醒后，先写 true，再计算其后真实产生的魔力量成长。\n\u003c% } %>\n经验来自本轮实际练习、应用、改良或突破。身体实际参与才有体能成果，纯想象动作不算肉身训练；回忆、跳章和翻日历不补造训练。\n只提交 /玩家/成长/经验/\u003c目标> 的非负整数终值与 /玩家/六维/\u003c目标> 的最终档位，不新建成长申请。经验只记魔力控制、体能、魔力量三项，彼此独立。\n已有经验与六维可据已确认事实纠错，包括未觉醒时的魔力量旧值；纠错不冒充新成长。\n经验是所提交评级的档内进度。门槛：F100、F+100、E150、E+150、D250、D+250、C400、C+400、B600、B+900、A1200、A+1600。达到门槛连续晋级，逐档扣除门槛并保留余量；S为顶档，保留余量。登记等级不随经验自动改变。\n\n【剧情、事件与日程】\n\u003c% if (updateWorld === 'rakudai') { %>\n宿舍按钮维护 /场景/宿舍 布尔值，缺项按 false；true 表示终端正在显示宿舍背景。模型不得进入宿舍、自动改地点或覆盖该标记，玩家主动点击离开由代码设 false。\n仅当本轮玩家指令为“休息”或“宿舍休息”，且旧 /场景/宿舍 为 true，才输出休息一晚及次日清晨的叙事，按上下文更新 /场景/时间（无明确日期不造日期），同时设 /场景/宿舍=false；保留地点和历史事件。非宿舍时拒绝这两个休息指令，不推进时间、不提交休息补丁。\n\u003c% } %>\n章节内容与完成标识以当前绑定条目为准，目录概要不能替代原文。实际入章设进行中；满足完成标识后可设已结束，或进入相邻节点并设进行中。本轮最多前进一个节点，主副共用进度；正文停在交接处，下一轮展开新章。未完成就保留，不因转场或战斗结束自动切章。\n每轮只承接玩家输入推进当前互动，不代写玩家的行动、内心或台词；需要玩家回答、决定或应对时停下，把行动权交还玩家。整章材料不要求一轮演完，不连续赶演多场战斗或章末结局。仅在玩家明确要求快进、跳过或概述时放宽，普通“继续”不算快进；不为切章赶进度，也不拖延已自然完成的交接。\n\u003c% if (updateWorld === 'rakudai') { %>\n落第：/场景/当前卷 用 1—19 的目录卷号，/场景/当前章 用注入目录键；手动向前切入使用终端。\n\u003c% } else { %>\n学战：/场景/当前卷 与已发生事件卷号保持 null，/场景/当前章 用注入条目的键（序章、第一章…终章）。目录没有下一个条目时保持当前章并停下，不改用落第卷章目录，也不擅自进入选拔赛、七星剑斗祭或 A/B 路线。\n\u003c% } %>\n完成事件归推进前章节；提示里可见的最近事件沿用原键补全，更早的事件只新增键名、不改写旧条目。只保存已发生结果，不写未来章节，不把不知情者列入。场景时间、地点、切入说明按实际情况更新，未知不编具体日期。日程只记本局已知安排，未知日期留空；实际开始或完成再改状态，完成另记事件。过期、缺席、未来原著安排不自动视为发生。取消或改期保留原条目和依据。\n\n【人际与分数】\n本局实际识别或明确认识的人物可建档；名单和传闻不等于见过。保留亲属、师生等背景关系，不因低分当陌生人。\n联系状态只记识别 / 已建立联系，首次双向言语或行动即建立联系；联系依据简记建立联系时的双方行动，后续日常互动不覆盖。已加联系方式独立，只在渠道成立时为 true，不以面对面交流代替。\n按事实补性别、身份、所属与已知资料；不填世界书秘密或未来资料。伐刀能力、灵装、煌武与星辰力按实际掌握记录，不因人物出身排除。校内序列与登记等级分别记录；已知正式登记或重评结果才填写登记等级。\n普通新人物好感 / 支援从 0 计，已确认背景可按实际深度直接核定。旧数字续算，不归零套初见奖励；未知或旧 null 保留待核定，事实明确时修正。\n好感表现对玩家态度的变化，支援表现落实的支持、协作和信任，二者独立。正常友善回应可有普通好感 +2—10；新生轻微好感、认可或防备缓和可参考 +11—20；重大关系改变可参考 +21—40。负向变化按实际影响核定，支援日常协作可参考 +1—5、克服阻碍 +6—10、重大协作 +10—15。这些为叙事尺度参考，不是硬上限。\n有对应回应就及时改分，不能只改态度印象；仍羞恼、没有恋爱、没有重大事件不等于无好感。只有玩家单方示好不强加对方好感；闲聊或许诺不自动增加协作支援。变化依据用一句简短事实记本轮变化与旧值→最终值，不追加历史旧依据，不要求固定关键词。一次回复给每人每项一个合并终值；后续可纠错终值，重放补丁不算新奖励。\n羁绊由支援派生（0—79未建立、80—159 C、160—239 B、240—319 A、320 S）。恋爱阶段只对已确认女性且好感有效者派生（0—199路人、200—499在意、500—799暧昧、800—999交往、1000生死相随）。阶段是表现参考，不倒补未发生的告白、婚约或亲密经历，不授予觉醒。\n\n\u003c% if (updateWorld === 'rakudai') { %>\n\u003crk-selection-rules>\n【破军选拔赛】\n/场景/选拔赛 保存本局名册与比赛，本卡默认20轮、288人号